const SUPABASE_URL = 'https://yqsdeufqbmkcznroieki.supabase.co';
const now     = new Date();
const today   = now.toISOString().slice(0, 10);
const statsFrom = new Date(now.getTime() - 30 * 86400000).toISOString().slice(0, 10);
const run_id  = 'run-' + Date.now() + '-' + Math.random().toString(36).slice(2, 9);

return [{ json: { SUPABASE_URL, run_id, stats_date_from: statsFrom, stats_date_to: today } }];

const cfg   = $('⚙️ Config').first().json;
const items = $input.all();

const campaigns = [];
for (const item of items) {
  const raw = item.json;
  const c = (raw && raw.campaign && raw.campaign.id) ? raw.campaign : raw;
  if (!c || !c.id) {
    console.warn('Item sin id ignorado:', JSON.stringify(raw).slice(0, 200));
    continue;
  }
  const nameLower = (c.name || '').toLowerCase();
  let vertical = 'unknown';
  if (nameLower.includes('window'))    vertical = 'windows';
  else if (nameLower.includes('roof')) vertical = 'roofing';

  campaigns.push({
    lp_campaign_id: String(c.id),
    name:           c.name || 'Sin nombre',
    public_name:    c.public_name || c.name || 'Sin nombre',
    vertical,
    status:         'active',
    updated_at:     new Date().toISOString(),
    run_id:       cfg.run_id,
    SUPABASE_URL: cfg.SUPABASE_URL,
  });
}

if (campaigns.length === 0) {
  throw new Error('Parsear Campañas: 0 campañas válidas. Primer item: ' + JSON.stringify($input.first().json).slice(0, 300));
}

console.log('Campañas encontradas: ' + campaigns.length);
return campaigns.map(c => ({ json: c }));

const allWatermarks = $('🕐 Leer Watermark').all();
const allCampaigns  = $('💾 Upsert lp_campaigns').all();
const cfg           = $('⚙️ Config').first().json;

return allCampaigns.map(c => {
  const campaign = c.json;
  const wm = allWatermarks.find(w => w.json.lp_campaign_id === campaign.lp_campaign_id)?.json || {};

  return {
    json: {
      lp_campaign_id: campaign.lp_campaign_id,
      name:           campaign.name     || wm.name,
      vertical:       campaign.vertical || wm.vertical,
      run_id:         cfg.run_id,
      SUPABASE_URL:   cfg.SUPABASE_URL,
      last_synced_at: wm.last_synced_at || null,
      sync_from_date: wm.sync_from_date || null,
    }
  };
});

const items = $input.all();
const cfg   = $('⚙️ Config').first().json;
// override_date_from/to solo se setean para backfills manuales
// stats_date_from/to son para el LP Stats API (Fetch Campañas) — no son override de watermark
const overrideFrom = cfg.override_date_from || null;
const overrideTo   = cfg.override_date_to   || null;

const results = items.map(item => {
  const data = item.json;
  if (!data || typeof data !== 'object') {
    return { json: { error: 'Datos de entrada inválidos', item: data } };
  }

  const now      = new Date();
  const today    = now.toISOString().slice(0, 10);
  const MAX_DAYS = 90;
  const minDate  = new Date(now.getTime() - MAX_DAYS * 86400000).toISOString().slice(0, 10);

  let dateFrom, dateTo;

  if (overrideFrom && overrideTo) {
    dateFrom = overrideFrom;
    dateTo   = overrideTo;
  } else {
    const lastSync = data.last_synced_at || null;
    const syncFrom = data.sync_from_date  || null;
    if (lastSync) {
      let d = new Date(lastSync);
      d.setDate(d.getDate() - 1);
      dateFrom = d.toISOString().slice(0, 10);
    } else if (syncFrom) {
      dateFrom = syncFrom;
    } else {
      dateFrom = minDate;
    }
    if (dateFrom < minDate) dateFrom = minDate;
    dateTo = today;
  }

  return {
    json: {
      lp_campaign_id: data.lp_campaign_id,
      name:           data.name     || 'Sin nombre',
      vertical:       data.vertical || 'Sin vertical',
      run_id:         data.run_id,
      SUPABASE_URL:   data.SUPABASE_URL,
      date_from:      dateFrom,
      date_to:        dateTo,
      debug_log:      `Fetch: ${dateFrom} -> ${dateTo}${overrideFrom ? ' (override)' : ' (watermark)'}`
    }
  };
});

return results;

const cfg  = $('⚙️ Config').first().json;
const logs = $input.all();

return logs.map(item => {
  const log = item.json;
  const logData = Array.isArray(log) ? log[0] : log;
  // String compare to avoid int vs string mismatch
  const campaignInfo = $('📅 Calcular Rango').all().find(c => String(c.json.lp_campaign_id) === String(logData.lp_campaign_id))?.json || {};

  return {
    json: {
      lp_campaign_id: String(logData.lp_campaign_id),
      name:           campaignInfo.name     || 'Sin nombre',
      vertical:       campaignInfo.vertical || 'Sin vertical',
      run_id:         cfg.run_id,
      SUPABASE_URL:   cfg.SUPABASE_URL,
      date_from:      logData.date_from  || campaignInfo.date_from,
      date_to:        logData.date_to    || campaignInfo.date_to,
      sync_log_id:    logData.id,
      search_after:   '',
      total_fetched:  0,
      total_inserted: 0
    }
  };
});

// Read campaign state: on page 1 from Init Loop; on page 2+ from Acumular Contadores
const initState  = $('🔄 Init Loop').item.json;
const accumState = $('🔁 Acumular Contadores').item ? $('🔁 Acumular Contadores').item.json : null;
const currentState = (accumState && accumState.sync_log_id) ? accumState : initState;

// Parse LP response — handles both {leads:[],search_after:''} and plain array
const httpResp = $input.item.json;
if (httpResp.statusCode && httpResp.statusCode >= 400) {
  throw new Error('LP API HTTP ' + httpResp.statusCode + ': ' + JSON.stringify(httpResp.body).slice(0, 200));
}
const body = (httpResp.body !== undefined) ? httpResp.body : httpResp;

let leads = [];
let nextSearchAfter = '';

if (Array.isArray(body)) {
  // Flat array response (no search_after from body)
  leads = body;
  nextSearchAfter = '';
} else if (body && typeof body === 'object') {
  // Object response: { leads: [...], search_after: '...' }
  // or { data: [...], search_after: '...' }
  leads = body.leads || body.data || [];
  nextSearchAfter = body.search_after || '';
}

const count  = leads.length;
const isDone = !nextSearchAfter || count === 0;

console.log('cursor=' + (currentState.search_after || 'first') + ' → ' + count + ' leads, next=' + (nextSearchAfter || 'done'));

const nameLower = (currentState.name || '').toLowerCase();
var vertical = currentState.vertical || 'unknown';
if (nameLower.includes('window'))    vertical = 'windows';
else if (nameLower.includes('roof')) vertical = 'roofing';

const rows = leads.map(function(lead) {
  var leadDate = null;
  if (lead.lead_date_ms) leadDate = new Date(parseInt(lead.lead_date_ms, 10)).toISOString();
  // supplier can be lead.supplier (object) or lead.suppliers (array)
  var sup = lead.supplier || (Array.isArray(lead.suppliers) ? lead.suppliers[0] : null) || {};
  var supplierId   = sup.id   ? String(sup.id)   : '';
  var supplierName = sup.name ? String(sup.name)  : '';

  const hashInput = JSON.stringify({ id: lead.id, status: lead.status, cost: lead.cost, revenue: lead.revenue });
  let hash = 0;
  for (let i = 0; i < hashInput.length; i++) { hash = ((hash << 5) - hash) + hashInput.charCodeAt(i); hash |= 0; }
  const row_hash = Math.abs(hash).toString(16).padStart(8, '0');

  return {
    leadprosper_lead_id: lead.id,
    row_hash,
    source:              'leadprosper_api',
    lp_campaign_id:      String(lead.campaign_id || currentState.lp_campaign_id),
    campaign_name:       lead.campaign_name || currentState.name,
    lead_created_at:     leadDate,
    status:              lead.status,
    lp_cost:             lead.cost    || 0,
    lp_revenue:          lead.revenue || 0,
    supplier_id_lp:      supplierId,
    supplier_name:       supplierName,
    vertical,
    raw_payload:         lead,
    buyers:              lead.buyers || [],
    processed_to_facts:  false,
    fetched_at:          new Date().toISOString(),
  };
});

return [{ json: {
  lp_campaign_id: currentState.lp_campaign_id,
  name:           currentState.name,
  vertical:       currentState.vertical,
  run_id:         currentState.run_id,
  SUPABASE_URL:   currentState.SUPABASE_URL,
  date_from:      currentState.date_from,
  date_to:        currentState.date_to,
  sync_log_id:    currentState.sync_log_id,
  search_after:   nextSearchAfter,
  total_fetched:  currentState.total_fetched + count,
  total_inserted: currentState.total_inserted,
  leads_batch:    rows,
  done:           isDone,
} }];

const state      = $('🔧 Transformar Leads').item.json;
const batchCount = state.leads_batch ? state.leads_batch.length : 0;

return [{ json: {
  lp_campaign_id: state.lp_campaign_id,
  name:           state.name,
  vertical:       state.vertical,
  run_id:         state.run_id,
  SUPABASE_URL:   state.SUPABASE_URL,
  date_from:      state.date_from,
  date_to:        state.date_to,
  sync_log_id:    state.sync_log_id,
  search_after:   state.search_after,
  total_fetched:  state.total_fetched,
  total_inserted: state.total_inserted + batchCount,
  done:           state.done,
} }];

// Leer el estado desde Acumular Contadores (siempre ejecutado antes en este path)
const state = $('🔁 Acumular Contadores').item.json;

if (!state || !state.lp_campaign_id) {
  throw new Error('Preparar Watermark: no hay lp_campaign_id. State: ' + JSON.stringify(state).slice(0, 200));
}

return [{ json: {
  lp_campaign_id: state.lp_campaign_id,
  sync_log_id:    state.sync_log_id,
  updated_at:     new Date().toISOString(),
} }];

const state = $input.first().json;
let sync_log_id    = state.sync_log_id    || null;
let lp_campaign_id = state.lp_campaign_id || null;
let error_message  = 'Error en ejecución del workflow — revisar logs de n8n';
if (state.error && state.error.message)  error_message = state.error.message;
else if (state.message)                  error_message = state.message;
console.error('ERROR HANDLER:', error_message);
return [{ json: { sync_log_id, lp_campaign_id, SUPABASE_URL: state.SUPABASE_URL || 'https://yqsdeufqbmkcznroieki.supabase.co', error_message, has_sync_log: sync_log_id !== null } }];

const resp = $input.first().json;
const errors = Array.isArray(resp.body) ? resp.body : (resp.body ? [resp.body] : []);
const run_id = $('⚙️ Config').first().json.run_id;
const error_count = errors.length;
const has_errors = error_count > 0;

let email_body = `Workflow: RP - LP API Ingesta\nRun ID: ${run_id}\nErrores encontrados: ${error_count}\n\n`;
if (has_errors) {
  email_body += errors.map((e, i) =>
    `${i + 1}. Campaña ${e.lp_campaign_id || 'N/A'}\n   Error: ${e.error_message || 'sin mensaje'}\n   Rango: ${e.date_from || '?'} → ${e.date_to || '?'}`
  ).join('\n\n');
}
email_body += '\n\nRevisar logs en n8n: https://n8n.rpworldllc.com';

return [{ json: { has_errors, error_count, run_id, email_body } }];
